"""Fictional tag utilities; no user data."""


def normalize_tags(text):
    """Return unique, nonempty tags in their first-occurrence order."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    result = []
    seen = set()
    for part in text.split(","):
        tag = part.strip().lower()
        if tag and tag not in seen:
            seen.add(tag)
            result.append(tag)
    return result

import unittest

from tags import normalize_tags


class NormalizeTagsTests(unittest.TestCase):
    def test_strips_and_lowercases_tags(self):
        self.assertEqual(normalize_tags(" News , PYTHON "), ["news", "python"])

    def test_omits_empty_tags(self):
        self.assertEqual(normalize_tags(" , News, ,  ,Tech, "), ["news", "tech"])

    def test_removes_normalized_duplicates_in_first_occurrence_order(self):
        self.assertEqual(
            normalize_tags(" Tech, news, TECH, Python, NEWS, tech "),
            ["tech", "news", "python"],
        )

    def test_empty_input_returns_empty_list(self):
        self.assertEqual(normalize_tags(""), [])

    def test_non_string_input_raises_type_error(self):
        for value in (None, 3, ["news"], b"news"):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    normalize_tags(value)


if __name__ == "__main__":
    unittest.main()

import unittest
from pathlib import Path

from tags import normalize_tags


class NormalizeTagsQATests(unittest.TestCase):
    def test_splits_strips_and_lowercases(self):
        self.assertEqual(
            normalize_tags(" News, PYTHON , Tech "),
            ["news", "python", "tech"],
        )

    def test_omits_empty_tags_from_repeated_and_trailing_commas(self):
        self.assertEqual(normalize_tags(", ,News,, Tech, "), ["news", "tech"])

    def test_removes_duplicates_after_normalization_in_first_order(self):
        self.assertEqual(
            normalize_tags(" Tech, news, TECH, Python, NEWS, tech "),
            ["tech", "news", "python"],
        )

    def test_empty_and_whitespace_only_input(self):
        for text in ("", "   ", " , , "):
            with self.subTest(text=text):
                self.assertEqual(normalize_tags(text), [])

    def test_non_string_inputs_raise_type_error(self):
        for value in (None, 0, 1.5, False, b"news", ["news"], ("news",), {"news": 1}, object()):
            with self.subTest(type=type(value).__name__):
                with self.assertRaises(TypeError):
                    normalize_tags(value)

    def test_readme_contains_usage_example_and_expected_output(self):
        readme = (Path(__file__).resolve().parent / "README.md").read_text(encoding="utf-8")
        example = 'print(normalize_tags(" News, python, news, , PYTHON, Tech "))'
        self.assertIn("from tags import normalize_tags", readme)
        self.assertIn(example, readme)
        self.assertIn("# ['news', 'python', 'tech']", readme)
        self.assertEqual(
            normalize_tags(" News, python, news, , PYTHON, Tech "),
            ["news", "python", "tech"],
        )


if __name__ == "__main__":
    unittest.main()

